class Program {
    static void Main() {
        int n = 7;
        int a = 0, b = 1;
        string output = "";
        for (int i = 0; i < n; i++) {
            output += a + (i < n - 1 ? " " : "");
            int next = a + b;
            a = b;
            b = next;
        }
        Console.WriteLine(output);
    }
}

