using System;

class Program {
    static void Main() {
        int a = 3, b = 4;
        string op = "*";
        int result = 0;
        switch (op) {
            case "+": result = a + b; break;
            case "-": result = a - b; break;
            case "*": result = a * b; break;
            default: result = a / b; break;
        }
        Console.WriteLine(result);
    }
}

